begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table resource_fixture(asset uuid,resource uuid,revision uuid,new_asset uuid,new_revision uuid);grant select,insert,update on resource_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99310000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Document course','Synthetic','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','99320000-0000-4000-8000-000000000001','99310000-0000-4000-8000-000000000001','Document unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','99330000-0000-4000-8000-000000000001','99320000-0000-4000-8000-000000000001','Worksheet lesson',1,'Review the worksheet');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update resource_fixture set asset=null;insert into resource_fixture(asset)values((internal.learning_resource_command('stage','99310000-0000-4000-8000-000000000001',null,null,null,'{"name":"ورقة.txt","contentType":"text/plain","byteSize":10,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','resource-stage',repeat('a',64),'resource-test')->>'id')::uuid);
select ok(not exists(select 1 from app.private_assets where id=(select asset from resource_fixture)),'course-purpose asset is absent from generic personal asset table projection');
select throws_ok($$select internal.learning_resource_command('attach','99310000-0000-4000-8000-000000000001','lesson','99330000-0000-4000-8000-000000000001',null,jsonb_build_object('assetId',(select asset from resource_fixture),'title','Worksheet','sequence',1),'resource-unverified',repeat('b',64),'resource-test')$$,'22023',null,'staged bytes cannot be attached');
reset role;update app.private_assets set state='AVAILABLE',available_at=now()where id=(select asset from resource_fixture);set local role cuevo_api;
update resource_fixture set resource=(internal.learning_resource_command('attach','99310000-0000-4000-8000-000000000001','lesson','99330000-0000-4000-8000-000000000001',null,jsonb_build_object('assetId',asset,'title','Worksheet','sequence',1),'resource-attach',repeat('b',64),'resource-test')->>'id')::uuid;
reset role;update resource_fixture set revision=(select revision_id from app.learning_resource_current where resource_id=resource_fixture.resource);set local role cuevo_api;
select is(jsonb_array_length(internal.read_learning_resource_page('99310000-0000-4000-8000-000000000001','lesson','99330000-0000-4000-8000-000000000001',100,null)->'items'),1,'managed teacher sees attached document');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(jsonb_array_length(internal.read_learning_resource_page('99310000-0000-4000-8000-000000000001','lesson','99330000-0000-4000-8000-000000000001',100,null)->'items'),0,'learner cannot enumerate attached unapproved document');
select throws_ok($$select internal.read_learning_resource_delivery((select resource from resource_fixture),(select revision from resource_fixture))$$,'42501',null,'unpublished document delivery denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update resource_fixture set new_revision=(internal.learning_resource_command('publish','99310000-0000-4000-8000-000000000001',null,null,resource,'{"expectedRevision":1,"confirmPublication":true}','resource-publish',repeat('c',64),'resource-test')->>'revisionId')::uuid;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((internal.read_learning_resource_delivery((select resource from resource_fixture),(select new_revision from resource_fixture))->'asset'->>'name'),'ورقة.txt','current learner delivers exact published Arabic filename');
select throws_ok($$select internal.read_learning_resource_delivery((select resource from resource_fixture),(select revision from resource_fixture))$$,'42501',null,'old unpublished revision cannot be substituted');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_learning_resource_delivery((select resource from resource_fixture),(select new_revision from resource_fixture))$$,'42501',null,'parent has no course-resource byte authority');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.asset_command('retire',(select asset from resource_fixture),'{"reason":"Wrong purpose route","confirmRetirement":true}','resource-generic-retire',repeat('d',64),'resource-test')$$,'42501',null,'generic asset commands cannot mutate resource purpose');
select internal.learning_resource_command('remove','99310000-0000-4000-8000-000000000001',null,null,(select resource from resource_fixture),'{"expectedRevision":2,"reason":"Teacher removes current worksheet","confirmRemoval":true}','resource-remove',repeat('d',64),'resource-test')is not null as removed;
select lives_ok($$select internal.learning_resource_command('remove','99310000-0000-4000-8000-000000000001',null,null,(select resource from resource_fixture),'{"expectedRevision":2,"reason":"Teacher removes current worksheet","confirmRemoval":true}','resource-remove',repeat('d',64),'resource-test')$$,'original removal key reconciles after current pointer changes');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.read_learning_resource_delivery((select resource from resource_fixture),(select new_revision from resource_fixture))$$,'42501',null,'removed current resource denies old published byte route');
select is(jsonb_array_length(internal.read_learning_resource_page('99310000-0000-4000-8000-000000000001','lesson','99330000-0000-4000-8000-000000000001',100,null)->'items'),0,'removed document leaves current learner list');
select ok(not has_table_privilege('cuevo_api','app.learning_resource_revisions','select'),'API has no raw resource-revision table grant');
select ok(not has_function_privilege('authenticated','internal.read_learning_resource_delivery(uuid,uuid)','execute'),'browser role has no direct protected delivery helper');
reset role;select is((select count(*)from app.learning_resource_revisions where resource_id=(select resource from resource_fixture)),3::bigint,'publication and removal preserve immutable revision history');
select*from finish();rollback;
